fn removeElement(nums: &mut Vec<i32>, val: i32) -> usize {
    // `write` is the index where we write the next non-`val` element.
    let mut write = 0;

    // Iterate over each element with index `read`.
    for read in 0..nums.len() {
        if nums[read] != val {
            // Overwrite the element at `write` with the one at `read`.
            nums[write] = nums[read];
            write += 1;
        }
    }

    // `write` is now the length of the prefix containing no `val`.
    write
}

